package tuckersoft.bandersnatch.controller;
import tuckersoft.bandersnatch.dto.DTOs; import tuckersoft.bandersnatch.service.PlaythroughService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/playthroughs") public class PlaythroughController{private final PlaythroughService s;public PlaythroughController(PlaythroughService s){this.s=s;}@PostMapping ResponseEntity<DTOs.PlaythroughResponse> create(@Valid @RequestBody DTOs.PlaythroughRequest r){return ResponseEntity.status(201).body(s.create(r));}@GetMapping List<DTOs.PlaythroughResponse> all(){return s.list();}@GetMapping("/{id}")DTOs.PlaythroughResponse get(@PathVariable long id){return s.get(id);}@GetMapping("/{id}/path")DTOs.PathResponse path(@PathVariable long id){return s.path(id);}}
